<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">           domain</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">parsed[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;domain&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
